//! Oracle rows and snapshot builders for the brush asset publication (L07-G / G06).
//!
//! `fixtures/bitmap-brush-resources-publish/oracle.txt` was generated by
//! `tools/gen_oracle.js` from baseline fbe4b8a3: P rows are PNGs written by an
//! independent encoder with their SOURCE pixels as the expectation; B and S rows
//! are the output of the VERBATIM `application/render/image-budget.js`
//! (`noteRegistered(id, w, h)`); U and X rows are shapes the existing decoder
//! must refuse as `Unsupported` / `Malformed`. Snapshots are real
//! `ObjectSnapshot`s admitted through `from_admitted_project`.

use super::{BrushAssetPublisher, BrushAssetRequest};
use crate::evaluation::object_scene_style_kernels::bitmap_brush_resources_store::BrushBitmapStore;
use crate::object_codec::{decode_allocated_project, encoded_wire_test, ImageAssetLimits};
use crate::object_document::{AssetId, AssetInventory, AssetKind, AssetRecord, AssetSource};
use crate::revision::{ImageResourceBudget, ObjectSnapshot};
use std::sync::Arc;

pub(crate) const ORACLE: &str = include_str!("fixtures/bitmap-brush-resources-publish/oracle.txt");

/// Data rows of one kind, without the tag.
pub(crate) fn rows(tag: char) -> Vec<&'static str> {
    ORACLE
        .lines()
        .filter(|line| line.starts_with(tag) && line[1..].starts_with(' '))
        .map(|line| &line[2..])
        .collect()
}

pub(crate) fn unhex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .chunks_exact(2)
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}

pub(crate) struct PngRow {
    pub(crate) name: &'static str,
    pub(crate) width: u32,
    pub(crate) height: u32,
    pub(crate) png: Vec<u8>,
    pub(crate) expected: Vec<u8>,
}

pub(crate) fn png_rows() -> Vec<PngRow> {
    rows('P')
        .into_iter()
        .map(|row| {
            let f: Vec<&str> = row.split(' ').collect();
            let (width, height): (u32, u32) = (f[1].parse().unwrap(), f[2].parse().unwrap());
            let expected = match f[5].strip_prefix("solid:") {
                Some(pixel) => unhex(pixel).repeat(width as usize * height as usize),
                None => unhex(f[5]),
            };
            PngRow {
                name: f[0],
                width,
                height,
                png: unhex(f[4]),
                expected,
            }
        })
        .collect()
}

pub(crate) fn png_row(name: &str) -> PngRow {
    png_rows()
        .into_iter()
        .find(|row| row.name == name)
        .unwrap_or_else(|| panic!("oracle has no P row {name}"))
}

/// Baseline `noteRegistered` bytes of one corpus entry (B rows).
pub(crate) fn baseline_cost(name: &str) -> usize {
    rows('B')
        .into_iter()
        .map(|row| row.split(' ').collect::<Vec<_>>())
        .find(|f| f[0] == name)
        .map(|f| f[3].parse().unwrap())
        .unwrap_or_else(|| panic!("oracle has no B row {name}"))
}

/// Rows `X`/`U`: `(name, png bytes)`.
pub(crate) fn blob_rows(tag: char) -> Vec<(&'static str, Vec<u8>)> {
    rows(tag)
        .into_iter()
        .map(|row| {
            let (name, hex) = row.split_once(' ').unwrap();
            (name, unhex(hex))
        })
        .collect()
}

/// Admission envelope of the tests; wide enough for every corpus entry.
pub(crate) fn limits() -> ImageAssetLimits {
    ImageAssetLimits::new(65536, 1 << 20, 16 << 20, 512, 512).unwrap()
}

pub(crate) enum Entry {
    Png(Arc<Vec<u8>>),
    Link(&'static str),
}
impl Entry {
    pub(crate) fn png(bytes: &[u8]) -> Self {
        Self::Png(Arc::new(bytes.to_vec()))
    }
}

fn base_project() -> crate::object_codec::ProjectEnvelope {
    decode_allocated_project(
        &serde_json::to_vec(&encoded_wire_test::wire()).unwrap(),
        encoded_wire_test::limits(),
        |n| Ok(vec![0; n]),
    )
    .unwrap()
}

/// A real snapshot (storage seam `from_admitted_project`) whose inventory holds `entries`.
pub(crate) fn snapshot(entries: &[(&str, AssetKind, &Entry)]) -> ObjectSnapshot {
    let mut records = Vec::new();
    for (id, kind, entry) in entries {
        let source = match entry {
            Entry::Png(bytes) => {
                AssetSource::admitted_embedded("image/png".to_string(), Arc::clone(bytes), 1 << 22)
                    .unwrap()
            }
            Entry::Link(locator) => AssetSource::linked(locator.to_string(), 4096).unwrap(),
        };
        let record = AssetRecord::new(
            AssetId::new(id.to_string()).unwrap(),
            id.to_string(),
            *kind,
            source,
        )
        .unwrap();
        records.push(Arc::new(record));
    }
    let inventory = AssetInventory::new(records, Vec::new(), 1024, 0).unwrap();
    let project = base_project().with_asset_inventory(Some(inventory));
    ObjectSnapshot::from_admitted_project("brush-asset".to_string(), project).unwrap()
}

pub(crate) fn snapshot_without_inventory() -> ObjectSnapshot {
    ObjectSnapshot::from_admitted_project("brush-asset".to_string(), base_project()).unwrap()
}

pub(crate) fn bare_drawing_snapshot() -> ObjectSnapshot {
    ObjectSnapshot::from_admitted("brush-asset".to_string(), base_project().drawing().clone())
        .unwrap()
}

/// An isolated hard quota of `limit` bytes with a publisher charging it.
pub(crate) fn fresh(limit: usize) -> (BrushAssetPublisher, ImageResourceBudget) {
    let budget = ImageResourceBudget::isolated(limit).unwrap();
    let store = BrushBitmapStore::with_budget(budget.clone());
    (BrushAssetPublisher::new(store), budget)
}

pub(crate) fn used(budget: &ImageResourceBudget) -> usize {
    budget.used().unwrap()
}

pub(crate) fn request<'a>(asset_id: &'a str, brush_id: &'a str) -> BrushAssetRequest<'a> {
    BrushAssetRequest {
        asset_id,
        brush_id,
        limits: limits(),
        expected_size: None,
    }
}

/// Indices at which two pixel buffers differ; a length difference is reported once as `usize::MAX`.
pub(crate) fn mismatches(actual: &[u8], expected: &[u8]) -> Vec<usize> {
    if actual.len() != expected.len() {
        return vec![usize::MAX];
    }
    (0..actual.len())
        .filter(|&i| actual[i] != expected[i])
        .collect()
}
